begin;
select plan(31);
insert into auth.users(id,instance_id,aud,role,email) values('fc000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','inviter@fixture.invalid');
insert into public.people(id,display_name) values('fc100000-0000-4000-8000-000000000001','Fictional Inviter'),('fc100000-0000-4000-8000-000000000002','Fictional Existing Person');
insert into public.auth_identities(person_id,auth_user_id,kind) values('fc100000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001','employee_email');
insert into public.memberships(person_id,kind,status) values('fc100000-0000-4000-8000-000000000001','employee','active');
insert into public.role_assignments(person_id,role_key,grant_reason) values('fc100000-0000-4000-8000-000000000001','elevated_admin','Fictional invitation test');
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values('fc200000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001','totp','verified',now(),now());
insert into auth.sessions(id,user_id,factor_id,aal,created_at,updated_at) values('fc300000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001','fc200000-0000-4000-8000-000000000001','aal2',now(),now());
insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values('fc400000-0000-4000-8000-000000000001','fc300000-0000-4000-8000-000000000001','totp',now(),now());
set local role authenticated;
set local request.jwt.claims='{"sub":"fc000000-0000-4000-8000-000000000001","session_id":"fc300000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}';
select is(public.current_person_can_invite_employees(),false,'password-only invitation authority denied');
select throws_ok($$select public.prepare_employee_invitation(null,'Fictional Employee','new@fixture.invalid',true)$$,'42501',null,'password-only preparation denied');
set local request.jwt.claims='{"sub":"fc000000-0000-4000-8000-000000000001","session_id":"fc300000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}';
select is(public.current_person_can_invite_employees(),true,'recent global elevated admin can prepare invitation');
select throws_ok($$select public.prepare_employee_invitation(null,'Fictional Employee','new@example.com',true)$$,'22023',null,'real recipient denied in fictional slice');
select throws_ok($$select public.prepare_employee_invitation(null,'Fictional Employee','new@fixture.invalid',false)$$,'22023',null,'duplicate review acknowledgment required');
select throws_ok($$select public.prepare_employee_invitation(null,'Fictional Employee','inviter@fixture.invalid',true)$$,'42501',null,'existing Auth identity cannot be silently reused');
select set_config('test.employee_invite',public.prepare_employee_invitation('fc100000-0000-4000-8000-000000000002',null,'new@fixture.invalid',true)::text,true);
select is((select masked_email from public.list_employee_invitations() where id=current_setting('test.employee_invite')::uuid),'ne…@fixture.invalid','queue exposes masked email only');
select throws_ok('select * from public.employee_invitations','42501',null,'browser cannot read private invitation records');
select throws_ok($$select public.prepare_employee_invitation('fc100000-0000-4000-8000-000000000002',null,'new@fixture.invalid',true)$$,'54000',null,'rapid reissue denied');
select is((select count(*)::integer from public.search_employee_invitation_people('Existing')),1,'bounded canonical duplicate review can find existing person');
reset role;
select is((select status::text from public.memberships where person_id='fc100000-0000-4000-8000-000000000002' and kind='employee'),'pending','invitation does not activate employee');
select is((select count(*)::integer from public.role_assignments where person_id='fc100000-0000-4000-8000-000000000002'),0,'invitation grants no role');
select is((select count(*)::integer from public.auth_identities where person_id='fc100000-0000-4000-8000-000000000002'),0,'preparation does not fabricate Auth identity');
select is((select count(*)::integer from public.security_audit_events where subject_person_id='fc100000-0000-4000-8000-000000000002' and event_type='employee_invitation_prepared'),1,'minimized preparation event recorded');
update auth.mfa_amr_claims set updated_at=now()-interval '20 minutes' where id='fc400000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.current_person_can_invite_employees(),false,'stale MFA cannot operate invitations');
reset role;
update auth.mfa_amr_claims set updated_at=now() where id='fc400000-0000-4000-8000-000000000001';
set local role authenticated;
select lives_ok($$select public.cancel_employee_invitation(current_setting('test.employee_invite')::uuid)$$,'authorized administrator can cancel');
select throws_ok($$select public.cancel_employee_invitation(current_setting('test.employee_invite')::uuid)$$,'55000',null,'cancellation replay denied');
reset role;
select is((select status from public.employee_invitations where id=current_setting('test.employee_invite')::uuid),'cancelled','cancelled state is durable');
update public.role_assignments set role_key='teacher' where person_id='fc100000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.current_person_can_invite_employees(),false,'Teacher cannot invite employees');
reset role;
update public.role_assignments set role_key='sales' where person_id='fc100000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.current_person_can_invite_employees(),false,'Sales cannot invite employees');
reset role;
update public.role_assignments set role_key='ordinary_admin' where person_id='fc100000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.current_person_can_invite_employees(),false,'ordinary Admin cannot invite employees');
select throws_ok($$select public.prepare_employee_invitation(null,'Fictional Employee','another@fixture.invalid',true)$$,'42501',null,'ordinary Admin preparation denied');
reset role;
update public.role_assignments set role_key='elevated_admin',revoked_at=now() where person_id='fc100000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.current_person_can_invite_employees(),false,'revoked issuer cannot invite');
reset role;
update public.role_assignments set revoked_at=null where person_id='fc100000-0000-4000-8000-000000000001';
update public.memberships set status='suspended' where person_id='fc100000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.current_person_can_invite_employees(),false,'suspended issuer cannot invite');
select throws_ok($$select public.prepare_employee_invitation(null,'Fictional Employee','another@fixture.invalid',true)$$,'42501',null,'suspended issuer preparation denied');
reset role;
update public.memberships set status='active' where person_id='fc100000-0000-4000-8000-000000000001';
update public.memberships set status='suspended' where person_id='fc100000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.prepare_employee_invitation('fc100000-0000-4000-8000-000000000002',null,'new@fixture.invalid',true)$$,'42501',null,'invitation cannot restore suspended employee');
reset role;
update public.memberships set status='ended' where person_id='fc100000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.prepare_employee_invitation('fc100000-0000-4000-8000-000000000002',null,'new@fixture.invalid',true)$$,'42501',null,'invitation cannot restore ended employee');
reset role;
update public.memberships set status='pending' where person_id='fc100000-0000-4000-8000-000000000002';
update public.people set status='archived' where id='fc100000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.prepare_employee_invitation('fc100000-0000-4000-8000-000000000002',null,'new@fixture.invalid',true)$$,'42501',null,'archived person cannot be invited');
reset role;
update public.people set status='active' where id='fc100000-0000-4000-8000-000000000002';
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at) values('fc000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','established@fixture.invalid',now());
insert into public.auth_identities(person_id,auth_user_id,kind) values('fc100000-0000-4000-8000-000000000002','fc000000-0000-4000-8000-000000000002','employee_email');
set local role authenticated;
select throws_ok($$select public.prepare_employee_invitation('fc100000-0000-4000-8000-000000000002',null,'changed@fixture.invalid',true)$$,'42501',null,'invitation cannot replace established email');
reset role;
set local role anon;
select throws_ok('select public.list_employee_invitations()','42501',null,'anonymous invitation queue denied');
select throws_ok('select public.current_person_can_invite_employees()','42501',null,'anonymous issuer capability denied');
select * from finish();
rollback;
